#!/usr/bin/env node
// Real-browser regression guard for the Proof-of-Funds **optional add-ons**
// (Verifier Reference + block-hash Freshness Anchor) in the exported PDF.
//
// The jsdom unit test (proof-of-funds-verifier-ref-anchor-pdf.test.tsx)
// captures the strings handed to a mocked jsPDF, which proves the content is
// *passed in* but cannot prove that a real PDF, generated by the live
// Vite-bundled jsPDF code path in a real browser, actually renders it. This
// script drives the real page in headless Chromium end-to-end:
//
//   1. creates a vault, seeds ONE funded address (a P2PKH address derived from
//      a script-held private key) via the CRUD modules, runs the OFFLINE
//      balance check, and fills the declarant fields
//   2. BASELINE run (both add-ons OFF): reads the on-screen challenge message,
//      signs it in Node with the held key (legacy Bitcoin Signed Message),
//      pastes the signature, verifies it through the REAL crypto path, and
//      downloads the generated PDF
//   3. ADD-ONS run: sets a Verifier Reference and a manual Freshness Anchor
//      (all external network access is blocked, so the anchor fetch fails and
//      the manual height/hash entry path is exercised), re-signs the changed
//      challenge, re-verifies, and downloads a second PDF
//
// Both PDFs are re-parsed with pdf.js (legacy build — the Nix-pinned Chromium
// predates Promise.try, same flavor as the other PDF checks) and asserted on:
//
//   Baseline PDF:
//     - the challenge message block appears EXACTLY as shown in the UI
//       (whitespace-normalized containment => no extra/reordered lines)
//     - NO "Verifier ref:" / "Block anchor:" lines and NO
//       "Verifier Reference:" / "Block Anchor:" appendix sentences anywhere
//   Add-ons PDF:
//     - the per-address challenge block includes the "Verifier ref: …" and
//       "Block anchor: <height> / <hash> (fetched …)" lines in-place
//     - the CHALLENGE MESSAGE FORMAT section includes the
//       'Verifier Reference: "…"' sentence and the
//       "Block Anchor: height …, hash …" sentence with the
//       "at or after block …" wording
//
// pdf.js is only the verification oracle (KYUTXO never reads PDFs).
//
// Usage: node scripts/check-pof-addons-pdf-browser.mjs
// Requires: a `chromium` binary on PATH (installed via Nix) and `playwright-core`.

import { chromium } from 'playwright-core';
import { execSync, spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import { secp256k1 } from '@noble/curves/secp256k1';
import * as bitcoin from 'bitcoinjs-lib';
import { acquireBrowserCheckLock } from './browser-check-lock.mjs';

// Serialize real-Chromium checks: parallel runs share port 5000 + CPU/RAM
// and crash each other (SIGTRAP, goto timeouts). Hold the lock for the whole
// script lifetime, including any dev-server spawn.
await acquireBrowserCheckLock();

const PORT = Number(process.env.KYUTXO_DEV_PORT || 5000);
const BASE_URL = `http://localhost:${PORT}/`;
const PROOF_URL = `${BASE_URL}proof-of-funds`;
const SETUP_PASSWORD = 'pof-addons-check-123';

const VERIFIER_REF = 'ACME Bank request #2026-777';
const ANCHOR_HEIGHT = 850000;
const ANCHOR_HASH =
  '00000000000000000002a7c4c1e48d76c5a37902165a270156b7a8d72728a054';

const FUNDED_SATS = 500_000;
const FUNDED_TXID =
  'c1b2c3d4e5f6071829304152637485960718293041526374859607182930c1b2';

// ── Script-held signing key (fixed, test-only) ────────────────────────────
// A fixed 32-byte private key; the P2PKH address is derived at runtime so the
// signature we produce always matches the address the page verifies.
const PRIV_KEY = Uint8Array.from(
  Buffer.from(
    '1111111111111111111111111111111111111111111111111111111111111111',
    'hex',
  ),
);
const PUB_KEY = secp256k1.getPublicKey(PRIV_KEY, true); // compressed
const SIGNER_ADDRESS = bitcoin.payments.p2pkh({
  pubkey: PUB_KEY,
  network: bitcoin.networks.bitcoin,
}).address;

function sha256(buf) {
  return createHash('sha256').update(buf).digest();
}

/** Legacy Bitcoin Signed Message hash: SHA256d(magic + varint + message). */
function legacyMessageHash(message) {
  const MAGIC = 'Bitcoin Signed Message:\n';
  const magicBytes = Buffer.from(MAGIC, 'utf8');
  const msgBytes = Buffer.from(message, 'utf8');
  const parts = [Buffer.from([magicBytes.length]), magicBytes];
  if (msgBytes.length < 253) {
    parts.push(Buffer.from([msgBytes.length]));
  } else {
    parts.push(
      Buffer.from([253, msgBytes.length & 0xff, (msgBytes.length >> 8) & 0xff]),
    );
  }
  parts.push(msgBytes);
  return sha256(sha256(Buffer.concat(parts)));
}

/** Produce the 65-byte base64 legacy signature for `message` with PRIV_KEY. */
function signLegacyMessage(message) {
  const hash = legacyMessageHash(message);
  const sig = secp256k1.sign(hash, PRIV_KEY);
  const compact = sig.toCompactRawBytes(); // 64 bytes r||s
  const header = 27 + sig.recovery + 4; // +4 => compressed pubkey
  const out = Buffer.concat([Buffer.from([header]), Buffer.from(compact)]);
  return out.toString('base64');
}

function resolveChromium() {
  if (process.env.CHROMIUM_BIN) return process.env.CHROMIUM_BIN;
  try {
    return execSync('which chromium', { encoding: 'utf8' }).trim();
  } catch {
    throw new Error(
      'No `chromium` binary found on PATH. Install it (Nix: chromium) or set CHROMIUM_BIN.',
    );
  }
}

async function isServerUp(url) {
  try {
    const res = await fetch(url, { method: 'GET' });
    return res.ok || res.status < 500;
  } catch {
    return false;
  }
}

async function waitForServer(url, timeoutMs) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (await isServerUp(url)) return true;
    await new Promise((r) => setTimeout(r, 1000));
  }
  return false;
}

/** Read a Playwright download into a Uint8Array of its bytes. */
async function readDownloadBytes(download) {
  const stream = await download.createReadStream();
  const chunks = [];
  for await (const chunk of stream) chunks.push(chunk);
  return new Uint8Array(Buffer.concat(chunks));
}

/** Parse PDF bytes with the legacy pdf.js build and return the full text. */
async function extractFullText(bytes) {
  const pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs');
  const loadingTask = pdfjs.getDocument({ data: bytes, isEvalSupported: false });
  const pdf = await loadingTask.promise;
  try {
    const pages = [];
    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const content = await page.getTextContent();
      pages.push(
        content.items.map((item) => ('str' in item ? item.str : '')).join(' '),
      );
      await page.cleanup();
    }
    return pages.join('\n');
  } finally {
    await pdf.cleanup();
    await loadingTask.destroy();
  }
}

/** Whitespace-insensitive normalization: pdf.js splits lines/columns with
 *  arbitrary spacing and splitTextToSize may wrap long tokens, so we compare
 *  with ALL whitespace removed. Containment of the full challenge string then
 *  still proves exact content and line ORDER with no inserted lines. */
const norm = (s) => s.replace(/\s+/g, '');

/** Sign the currently displayed challenge for row 0, paste it and verify. */
async function signAndVerifyRow0(page, expectSubstring) {
  // <pre data-testid="text-challenge-0"> holds the exact challenge text.
  const challengeEl = page.getByTestId('text-challenge-0');
  await challengeEl.waitFor({ state: 'visible', timeout: 20_000 });
  if (expectSubstring) {
    await page.waitForFunction(
      (needle) => {
        const el = document.querySelector('[data-testid="text-challenge-0"]');
        return el && el.textContent && el.textContent.includes(needle);
      },
      expectSubstring,
      { timeout: 20_000 },
    );
  }
  const challenge = await challengeEl.evaluate((el) => el.textContent);
  const sigBase64 = signLegacyMessage(challenge);
  const sigBox = page.getByTestId('textarea-signature-0');
  await sigBox.scrollIntoViewIfNeeded({ timeout: 10_000 });
  await sigBox.fill(sigBase64);
  await page.getByTestId('button-verify-0').click();
  await page
    .getByText(/1 of 1 address control-verified/i)
    .first()
    .waitFor({ state: 'visible', timeout: 30_000 });
  return challenge;
}

async function generatePdfBytes(page) {
  const pdfBtn = page.getByTestId('button-generate-pdf');
  await page.waitForFunction(
    () => {
      const b = document.querySelector('[data-testid="button-generate-pdf"]');
      return b && !b.hasAttribute('disabled');
    },
    { timeout: 20_000 },
  );
  await pdfBtn.scrollIntoViewIfNeeded({ timeout: 10_000 });
  const [download] = await Promise.all([
    page.waitForEvent('download', { timeout: 90_000 }),
    pdfBtn.click(),
  ]);
  return readDownloadBytes(download);
}

async function main() {
  const exe = resolveChromium();
  console.log(`[pof-addons-pdf] chromium: ${exe}`);
  console.log(`[pof-addons-pdf] signer address: ${SIGNER_ADDRESS}`);

  let devProc = null;
  let startedServer = false;

  if (await isServerUp(BASE_URL)) {
    console.log(`[pof-addons-pdf] reusing dev server at ${BASE_URL}`);
  } else {
    console.log(`[pof-addons-pdf] starting dev server (npm run dev) ...`);
    devProc = spawn('npm', ['run', 'dev'], {
      stdio: ['ignore', 'inherit', 'inherit'],
      env: process.env,
      detached: true,
    });
    startedServer = true;
    const ready = await waitForServer(BASE_URL, 90_000);
    if (!ready) {
      throw new Error(`Dev server did not become ready at ${BASE_URL} within 90s.`);
    }
    console.log(`[pof-addons-pdf] dev server ready at ${BASE_URL}`);
  }

  const browser = await chromium.launch({
    executablePath: exe,
    headless: true,
    args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
  });

  let baselinePdfBytes = null;
  let addonsPdfBytes = null;
  let baselineChallenge = null;
  let addonsChallenge = null;

  try {
    const context = await browser.newContext({
      serviceWorkers: 'block',
      acceptDownloads: true,
    });
    // Block ALL non-local network access: the freshness-anchor fetch must fail
    // deterministically so the manual height/hash entry path is exercised.
    await context.route('**/*', (route) => {
      const url = route.request().url();
      if (url.startsWith(BASE_URL) || url.startsWith('data:')) {
        return route.continue();
      }
      return route.abort();
    });
    const page = await context.newPage();
    page.on('console', (msg) => {
      const t = msg.text();
      if (t.toLowerCase().includes('error')) {
        console.log(`[pof-addons-pdf][page-console] ${t}`);
      }
    });

    await page.goto(PROOF_URL, { waitUntil: 'load', timeout: 60_000 });

    // ── Create the vault ───────────────────────────────────────────────────
    const pwInput = page.getByTestId('input-password');
    await pwInput.waitFor({ state: 'visible', timeout: 30_000 });
    await pwInput.fill(SETUP_PASSWORD);
    const confirmInput = page.getByTestId('input-confirm-password');
    await confirmInput.waitFor({ state: 'visible', timeout: 10_000 });
    await confirmInput.fill(SETUP_PASSWORD);
    await page.getByTestId('button-submit').click();

    const textarea = page.getByTestId('textarea-address-input');
    await textarea.waitFor({ state: 'visible', timeout: 30_000 });

    // ── Seed the funded address (offline balance source reads these rows) ──
    await page.evaluate(
      async ({ addr, sats, txid }) => {
        const txCrud = await import('/src/lib/data/transaction-crud.ts');
        const now = Math.floor(Date.now() / 1000);
        await txCrud.addTransaction({
          txid,
          blockHeight: 800_000,
          blockTime: now - 3600,
          fee: 1000,
          feeRate: 5,
          syncedAt: Date.now(),
        });
        await txCrud.addParticipant({
          txid,
          role: 'output',
          address: addr,
          amount: sats,
          vout: 0,
        });
        return true;
      },
      { addr: SIGNER_ADDRESS, sats: FUNDED_SATS, txid: FUNDED_TXID },
    );

    // ── Offline balance check ──────────────────────────────────────────────
    await page.getByTestId('button-source-offline').click();
    await textarea.fill(SIGNER_ADDRESS);
    await page.getByTestId('button-check-balances').click();
    await page
      .locator('[data-testid="row-address-0"]')
      .waitFor({ state: 'visible', timeout: 20_000 });

    // ── Declarant fields ───────────────────────────────────────────────────
    await page.getByTestId('input-declarant-name').fill('Alice Example');
    await page.getByTestId('input-declaration-date').fill('2026-06-30');
    await page.getByTestId('input-purpose').fill('Bank account opening');

    // ════════════════════════════════════════════════════════════════════
    // RUN 1 — BASELINE (both add-ons off): verify + generate PDF
    // ════════════════════════════════════════════════════════════════════
    baselineChallenge = await signAndVerifyRow0(page, null);
    console.log('[pof-addons-pdf] baseline challenge verified');
    baselinePdfBytes = await generatePdfBytes(page);
    console.log(
      `[pof-addons-pdf] captured baseline PDF (${baselinePdfBytes.byteLength} bytes)`,
    );

    // ════════════════════════════════════════════════════════════════════
    // RUN 2 — ADD-ONS ON: verifier reference + manual freshness anchor
    // ════════════════════════════════════════════════════════════════════
    await page.getByTestId('button-proof-addons-toggle').click();
    await page.getByTestId('input-verifier-reference').fill(VERIFIER_REF);

    // Turn the anchor switch on; the fetch fails (network blocked / no node),
    // surfacing the manual entry inputs.
    const anchorSwitch = page.getByTestId('switch-freshness-anchor');
    await anchorSwitch.scrollIntoViewIfNeeded({ timeout: 10_000 });
    if ((await anchorSwitch.getAttribute('data-state')) !== 'checked') {
      await anchorSwitch.click();
    }
    const manualHeight = page.getByTestId('input-freshness-manual-height');
    await manualHeight.waitFor({ state: 'visible', timeout: 30_000 });
    await manualHeight.fill(String(ANCHOR_HEIGHT));
    await page.getByTestId('input-freshness-manual-hash').fill(ANCHOR_HASH);
    await page.getByTestId('button-apply-manual-freshness').click();
    await page
      .getByText(`Height: ${ANCHOR_HEIGHT}`)
      .first()
      .waitFor({ state: 'visible', timeout: 15_000 });

    // Re-sign + re-verify: the challenge now carries both add-on lines.
    addonsChallenge = await signAndVerifyRow0(page, 'Block anchor:');
    console.log('[pof-addons-pdf] add-ons challenge verified');
    addonsPdfBytes = await generatePdfBytes(page);
    console.log(
      `[pof-addons-pdf] captured add-ons PDF (${addonsPdfBytes.byteLength} bytes)`,
    );
  } finally {
    await browser.close();
    if (startedServer && devProc) {
      try {
        process.kill(-devProc.pid, 'SIGTERM');
      } catch {
        try {
          devProc.kill('SIGTERM');
        } catch {
          /* ignore */
        }
      }
    }
  }

  // ── Parse + assert (Node side; pdf.js is only the oracle) ────────────────
  const baselineText = await extractFullText(baselinePdfBytes);
  const addonsText = await extractFullText(addonsPdfBytes);
  const nBaseline = norm(baselineText);
  const nAddons = norm(addonsText);

  const steps = [];

  // Sanity: the UI baseline challenge itself has no add-on lines.
  steps.push({
    name: 'sanity: baseline UI challenge has no add-on lines',
    passed:
      !baselineChallenge.includes('Verifier ref:') &&
      !baselineChallenge.includes('Block anchor:'),
    detail: JSON.stringify(baselineChallenge.split('\n')),
  });

  // 1) Baseline PDF renders the challenge EXACTLY as shown in the UI
  //    (containment of the whole normalized string = unchanged, no extra lines).
  steps.push({
    name: 'baseline PDF: challenge block matches the UI text exactly (no extra lines)',
    passed: nBaseline.includes(norm(baselineChallenge)),
    detail: 'whitespace-normalized containment of the full challenge string',
  });

  // 2) Baseline PDF carries NO add-on text anywhere.
  {
    const forbidden = [
      'Verifier ref:',
      'Block anchor:',
      'Verifier Reference:',
      'Block Anchor:',
      'at or after',
      VERIFIER_REF,
      ANCHOR_HASH,
    ];
    const leaked = forbidden.filter((f) => nBaseline.includes(norm(f)));
    steps.push({
      name: 'baseline PDF: no verifier-reference / block-anchor text anywhere',
      passed: leaked.length === 0,
      detail: leaked.length === 0 ? 'no forbidden tokens' : `leaked: ${leaked.join(' | ')}`,
    });
  }

  // 3) Add-ons UI challenge carries both lines, in-place before the Address line.
  {
    const lines = addonsChallenge.split('\n');
    const iVer = lines.findIndex((l) => l === `Verifier ref: ${VERIFIER_REF}`);
    const iAnchor = lines.findIndex((l) =>
      l.startsWith(`Block anchor: ${ANCHOR_HEIGHT} / ${ANCHOR_HASH} (fetched `),
    );
    const iAddr = lines.findIndex((l) => l.startsWith('Address:'));
    const passed = iVer >= 0 && iAnchor === iVer + 1 && iAddr === iAnchor + 1;
    steps.push({
      name: 'add-ons UI challenge: both lines present, ordered before Address',
      passed,
      detail: `verifier@${iVer} anchor@${iAnchor} address@${iAddr}`,
    });
  }

  // 4) Add-ons PDF renders that exact challenge block (both optional lines
  //    included, correct order, nothing else inserted).
  steps.push({
    name: 'add-ons PDF: challenge block includes both add-on lines exactly as signed',
    passed: nAddons.includes(norm(addonsChallenge)),
    detail: 'whitespace-normalized containment of the full add-on challenge string',
  });

  // 5) CHALLENGE MESSAGE FORMAT section: Verifier Reference sentence.
  {
    const passed =
      nAddons.includes(norm(`Verifier Reference: "${VERIFIER_REF}"`)) &&
      nAddons.includes(
        norm('a free-text identifier provided by the requesting party'),
      );
    steps.push({
      name: 'add-ons PDF: appendix includes the "Verifier Reference: …" sentence',
      passed,
      detail: passed ? 'sentence present' : 'sentence missing from appendix',
    });
  }

  // 6) CHALLENGE MESSAGE FORMAT section: Block Anchor sentence with the
  //    "at or after" wording.
  {
    const passed =
      nAddons.includes(
        norm(`Block Anchor: height ${ANCHOR_HEIGHT}, hash ${ANCHOR_HASH}`),
      ) && nAddons.includes(norm(`at or after block ${ANCHOR_HEIGHT}`));
    steps.push({
      name: 'add-ons PDF: appendix includes the "Block Anchor: height/hash … at or after" sentence',
      passed,
      detail: passed ? 'sentence present' : 'sentence missing from appendix',
    });
  }

  const ok = steps.every((s) => s.passed);
  console.log(`[pof-addons-pdf] ok=${ok}`);
  for (const s of steps) {
    console.log(`  [${s.passed ? 'PASS' : 'FAIL'}] ${s.name} :: ${s.detail}`);
  }

  if (!ok) {
    console.error('\n[pof-addons-pdf] FAILED:');
    for (const s of steps.filter((s) => !s.passed)) {
      console.error(`  - ${s.name}: ${s.detail}`);
    }
    process.exit(1);
  }

  console.log(
    '[pof-addons-pdf] PASSED: verifier reference and block anchor render correctly in the exported PDF (and stay out of the baseline).',
  );
}

main().catch((err) => {
  console.error('[pof-addons-pdf] ERROR:', err && err.stack ? err.stack : err);
  process.exit(1);
});
